fn to_str(n: Int) -> Str {
    if n == 0 {
        return Str("0")
    }
    let mut result = Str("")
    let mut tmp = n
    while tmp > 0 {
        let digit = trunc(tmp % 10)
        result = concat(result, char(digit)?)
        tmp = trunc(tmp / 10)
    }
    result
}

fn str_len(s: Str) -> Int {
    let mut result = 0
    for _ in chars(s) {
        result = result + 1
    }
    result
}

fn chars(s: Str) -> Vec<Int> {
    let mut result = vec()
    let mut i = 0
    while i < str_len(s) {
        result = push(result, int_to_str(get(s, i)?)?)
        i = i + 1
    }
    result
}

fn int_to_str(n: Int) -> Str {
    if n == 0 {
        return Str("0")
    }
    let mut result = Str("")
    let mut tmp = n
    if tmp < 0 {
        result = concat(result, Str("-"))
        tmp = trunc(tmp / -1)
    }
    while tmp > 0 {
        let digit = trunc(tmp % 10)
        result = concat(result, char(digit)?)
        tmp = trunc(tmp / 10)
    }
    result
}

fn trunc(x: Float) -> Int {
    let mut result = Int(0)
    if x >= 0.0 {
        result = Int(x)
    } else {
        result = Int(x - 0.5)
    }
    result
}

